import { mapState } from "vuex";
import {
  regionList,
  agentFrom,
  isShowApi,
  clerkList,
  staffAddFrom,
} from "@/api/agent";
import { formatDate } from "@/utils/validate";
export default {
  name: "agent_extra",
  data() {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      total: 0,
      total2: 0,
      userLists: [],
      columns2: [
        {
          title: "用户UID",
          key: "uid",
          minWidth: 80,
        },

        {
          title: "头像",
          slot: "avatar",
          minWidth: 90,
        },
        {
          title: "姓名",
          key: "nickname",
          minWidth: 90,
        },
        {
          title: "分销比例",
          key: "division_percent",
          minWidth: 80,
        },
        {
          title: "操作",
          slot: "action",
          width: 90,
        },
      ],
      columns: [
        {
          title: "用户UID",
          key: "uid",
          width: 80,
        },

        {
          title: "头像",
          slot: "avatar",
          width: 90,
        },
        {
          title: "名称",
          key: "division_name",
          width: 80,
        },
        {
          title: "分销比例",
          key: "division_percent",
          minWdith: 130,
        },
        {
          title: "员工数量",
          key: "down_num",
          minWdith: 130,
        },
        {
          title: "截止时间",
          key: "division_end_time",
          minWdith: 130,
        },
        {
          title: "状态",
          slot: "division_status",
          minWdith: 130,
        },
        {
          title: "操作",
          slot: "action",
          width: 220,
        },
      ],
      formInline: {
        uid: 0,
        proportion: 0,
        image: "",
      },
      FromData: null,
      loading: false,
      current: 0,
      formValidate: {
        page: 1,
        limit: 15,
        keyword: "",
      },
      staffModal: false,
      clerkReqData: {
        uid: 0,
        page: 1,
        limit: 15,
      },
      clerkLists: [],
    };
  },
  filters: {
    formatDate(time) {
      if (time !== 0) {
        let date = new Date(time * 1000);
        return formatDate(date, "yyyy-MM-dd hh:mm");
      }
    },
  },
  computed: {
    ...mapState("media", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 80;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.getList();
  },
  methods: {
    // 搜索
    userSearchs() {
      this.formValidate.page = 1;
      this.getList();
    },
    jump(uid) {
      this.clerkReqData.uid = uid;
      this.getClerkList();
    },
    getClerkList() {
      this.clerkReqData.division_type = 3;
      clerkList(this.clerkReqData).then((res) => {
        this.clerkLists = res.data.list;
        this.total2 = res.data.count;
        this.staffModal = true;
      });
    },
    // 列表
    getList() {
      this.loading = true;
      this.formValidate.division_type = 2;
      regionList(this.formValidate)
        .then(async (res) => {
          let data = res.data;
          this.userLists = data.list;
          this.total = data.count;
          this.loading = false;
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    // 添加表单
    groupAdd(id) {
      this.$modalForm(agentFrom(id))
        .then((res) => {
          this.getList();
        })
        .catch((err) => {});
    },
    //添加员工表单
    staffAdd(id) {
      this.$modalForm(staffAddFrom(id))
        .then((res) => {
          this.getList();
        })
        .catch((err) => {});
    },
    // 修改是否显示
    onchangeIsShow(row) {
      let data = {
        id: row.uid,
        status: row.division_status,
      };
      isShowApi(data)
        .then(async (res) => {
          this.$Message.success(res.msg);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    /*
     * 删除
     * row 当前行数据
     * tit 提示语
     * num 删除的行数
     * list 删除的数组
     */
    del(row, tit, num, list) {
      let delfromData = {
        title: tit,
        method: "DELETE",
        uid: row.uid,
        url: `agent/division/del/${row.uid}`,
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this[list].splice(num, 1);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
  },
};
